mapper.select:
SELECT e.id, e.real_name AS realName, e.department_id AS departmentId, d.dept_name AS departmentName, e.regist_level_id AS registLevelId, r.regist_name AS registLevelName, e.scheduling_id AS schedulingId, s.rule_name AS schedulingName, e.active FROM employee e JOIN department d ON d.id = e.department_id LEFT JOIN regist_level r ON r.id = e.regist_level_id LEFT JOIN scheduling s ON s.id = e.scheduling_id WHERE e.active = TRUE AND e.department_id = #{departmentId}
AND (e.real_name LIKE CONCAT('%', #{keyword}, '%') OR d.dept_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY e.id

SELECT id, regist_code AS code, regist_name AS name, active FROM regist_level WHERE active = TRUE
AND (regist_code LIKE CONCAT('%', #{keyword}, '%') OR regist_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY sequence_no, regist_code LIMIT #{limit} OFFSET #{offset}

SELECT id, settle_code AS code, settle_name AS name, active FROM settle_category WHERE active = TRUE
AND (settle_code LIKE CONCAT('%', #{keyword}, '%') OR settle_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY sequence_no, settle_code LIMIT #{limit} OFFSET #{offset}

SELECT id, disease_code AS code, disease_name AS name, disease_icd AS icd, disease_category AS category, active FROM disease WHERE active = TRUE
AND ( disease_code LIKE CONCAT('%', #{keyword}, '%') OR disease_name LIKE CONCAT('%', #{keyword}, '%') OR disease_icd LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY disease_code LIMIT #{limit} OFFSET #{offset}

SELECT id, drug_code AS code, drug_name AS name, drug_format AS format, drug_unit AS unit, manufacturer, drug_dosage AS dosage, drug_type AS type, drug_price AS price, mnemonic_code AS mnemonicCode, active FROM drug_info WHERE active = TRUE
AND ( drug_code LIKE CONCAT('%', #{keyword}, '%') OR drug_name LIKE CONCAT('%', #{keyword}, '%') OR mnemonic_code LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY drug_code LIMIT #{limit} OFFSET #{offset}

SELECT mt.id, mt.tech_code AS code, mt.tech_name AS name, mt.tech_format AS format, mt.tech_price AS price, mt.tech_type AS type, mt.price_type AS priceType, mt.department_id AS departmentId, d.dept_name AS departmentName, mt.active FROM medical_technology mt JOIN department d ON d.id = mt.department_id WHERE mt.active = TRUE
AND (mt.tech_code LIKE CONCAT('%', #{keyword}, '%') OR mt.tech_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY mt.tech_code LIMIT #{limit} OFFSET #{offset}
